// Generated by bildr from .bildr/datasources/weather.json. Editing this file detaches it from the editor.
import { describe, expect, it } from 'vitest'
import { err, ok } from '#core/kernel/result'
import { remoteFailed } from '../../shared/domain/weather/errors'
import { reportForecast } from '../../shared/domain/weather/use-cases/report-forecast'
import { fakeWeatherRepository } from './fake-repository'

describe('reportForecast', () => {
  it('returns what the API answers', async () => {
    const repository = fakeWeatherRepository({ reportForecast: async () => ok({
      city: 'city 1',
      celsius: 1.5,
      observedAt: '2024-01-02T03:04:05.000Z'
    }) })
    const result = await reportForecast({ weather: repository })({
      body: {
        city: 'city 1',
        celsius: 1.5,
        observedAt: '2024-01-02T03:04:05.000Z'
      }
    })
    expect(result).toEqual({ ok: true, value: {
      city: 'city 1',
      celsius: 1.5,
      observedAt: '2024-01-02T03:04:05.000Z'
    } })
  })

  it('returns a failure of the API as a remote_failed error', async () => {
    const repository = fakeWeatherRepository({ reportForecast: async () => err(remoteFailed(503, 'answered 503')) })
    const result = await reportForecast({ weather: repository })({
      body: {
        city: 'city 1',
        celsius: 1.5,
        observedAt: '2024-01-02T03:04:05.000Z'
      }
    })
    expect(result).toEqual({ ok: false, error: expect.objectContaining({ type: 'remote_failed', status: 503 }) })
  })

  it('refuses an input that is not valid, without calling the API', async () => {
    const repository = fakeWeatherRepository()
    const result = await reportForecast({ weather: repository })({ body: 'wrong' } as never)
    expect(result).toEqual({ ok: false, error: expect.objectContaining({ type: 'invalid_input' }) })
  })
})
